from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Lossless bounded optimizer for character-prefix reuse in serialized rows."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional source dataframe and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Convert a scalar to evaluator text, mapping scalar missing values to ''."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return common-prefix length using binary-searched C-level slice comparisons."""
        high = min(len(left), len(right))
        low = 0
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Compute ideal character-Trie reuse from sorted adjacent serialized rows."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            total += cls._lcp(previous, current)
            previous = current
        return total

    @staticmethod
    def _make_strings(cells, orders) -> List[str]:
        """Serialize every source row using its complete row-specific column order."""
        return [
            "".join(cells[row, column] for column in orders[row])
            for row in range(cells.shape[0])
        ]

    def _global_order(self, cells, mode: int = 0) -> List[int]:
        """Rank columns by length-weighted repeated values with deterministic ties."""
        n, m = cells.shape
        ranked = []

        for column in range(m):
            counts = {}
            total_length = 0

            for value in cells[:, column]:
                counts[value] = counts.get(value, 0) + 1
                total_length += len(value)

            weighted = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            repetition = sum(
                count * (count - 1)
                for count in counts.values()
            )

            if mode == 0:
                score = weighted
            else:
                score = weighted + repetition * max(
                    1, total_length // max(1, n)
                )

            ranked.append((score, column))

        ranked.sort(key=lambda item: (-item[0], item[1]))
        return [column for _, column in ranked]

    def _prototype_orders(self, cells, tail) -> List[List[int]]:
        """
        Build row-specific prefix-frontier permutations.

        Rows are placed into first-character buckets using their serialization under
        the global frequency-ranked tail.  Each bucket keeps at most eight distinct
        lexicographic prototypes.  Every row is assigned to its closest prototype,
        then greedily chooses at most three leading fields whose concatenation has
        the longest common prefix with that prototype.  The remaining fields are
        appended in global-ranked order.
        """
        n, m = cells.shape
        if n == 0 or m == 0:
            return [[] for _ in range(n)]

        base = [
            "".join(cells[row, column] for column in tail)
            for row in range(n)
        ]

        buckets = {}
        for row, text in enumerate(base):
            signature = text[:1]
            buckets.setdefault(signature, []).append(row)

        result = [None] * n
        frontier_limit = min(3, m)

        for rows in buckets.values():
            representatives = []
            seen = set()

            for row in sorted(rows, key=lambda item: (base[item], item)):
                value = base[row]
                if value not in seen:
                    seen.add(value)
                    representatives.append(row)
                    if len(representatives) >= 8:
                        break

            if not representatives:
                representatives = [rows[0]]

            assignments = {}
            for row in rows:
                best_rep = representatives[0]
                best_match = self._lcp(base[row], base[best_rep])

                for rep in representatives[1:]:
                    match = self._lcp(base[row], base[rep])
                    if match > best_match or (
                        match == best_match and rep < best_rep
                    ):
                        best_rep = rep
                        best_match = match

                assignments.setdefault(best_rep, []).append(row)

            for representative, group in assignments.items():
                prototype = base[representative]

                for row in group:
                    unused = set(range(m))
                    chosen = []
                    prefix = ""

                    for _ in range(frontier_limit):
                        best_column = None
                        best_match = -1

                        for column in sorted(unused):
                            trial = prefix + cells[row, column]
                            match = self._lcp(trial, prototype)

                            if match > best_match:
                                best_match = match
                                best_column = column

                        if best_column is None:
                            break

                        chosen.append(best_column)
                        unused.remove(best_column)
                        prefix += cells[row, best_column]

                    for column in tail:
                        if column in unused:
                            chosen.append(column)
                            unused.remove(column)

                    if unused:
                        chosen.extend(sorted(unused))

                    result[row] = chosen

        return result

    def _candidate(self, cells, orders):
        """Serialize one candidate, compute exact reuse, and return stable row order."""
        strings = self._make_strings(cells, orders)
        score = self._trie_score(strings)
        row_order = sorted(
            range(len(strings)),
            key=lambda row: (strings[row], row),
        )
        return score, strings, row_order

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate two global orders and one character-prefix-frontier candidate."""
        n, m = df.shape
        self.num_rows = n
        self.num_cols = m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)

        for row in range(n):
            for column in range(m):
                cells[row, column] = self._cell_text(raw[row, column])

        weighted_order = self._global_order(cells, 0)
        mixed_order = self._global_order(cells, 1)
        frontier_orders = self._prototype_orders(cells, weighted_order)

        candidates = [
            [weighted_order[:] for _ in range(n)],
            [mixed_order[:] for _ in range(n)],
            frontier_orders,
        ]

        best = None
        for orders in candidates:
            score, strings, row_order = self._candidate(cells, orders)
            signature = tuple(orders[0]) if orders else ()
            tie_break = tuple(-column for column in signature)
            choice = (score, tie_break)

            if best is None or choice > best[0]:
                best = (choice, strings, row_order, orders)

        _, strings, row_order, orders = best

        output = np.empty((n, m), dtype=object)
        column_orders = []

        for destination, source in enumerate(row_order):
            source_order = orders[source]
            output[destination, :] = [
                raw[source, column] for column in source_order
            ]
            column_orders.append([
                df.columns[column] for column in source_order
            ])

        result = pd.DataFrame(output, columns=df.columns)
        return result, column_orders

